// 2026-11-04: подписи ссылок обновлены по принятому #aeae17 (шапка и футер — «מחשבון רכישת עסק»; H1 без изменений).
import { test, expect } from '@playwright/test';
import { prepareReadOnly, DEVICES, LOAD } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Калькулятор — экран', () => {
  for (const tag of DEVICES) {
    test(`Ссылки в шапке и футере ведут на /calculator #3e4835 #aeae17 ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      // На первом заходе может всплыть окно PWA «אל תחמיצו אף הזדמנות» — закрыть «אולי מאוחר יותר».
      await page.addLocatorHandler(page.getByRole('button', { name: 'אולי מאוחר יותר' }), (b) => b.click());
      await page.goto('/');

      const headerLink = page.locator('header').getByRole('link', { name: 'מחשבון רכישת עסק', exact: true });
      const footerLink = page.locator('footer').getByRole('link', { name: 'מחשבון רכישת עסק', exact: true });
      // На мобайле ссылка шапки — внутри меню (скрыта), поэтому проверяется href.
      await expect(headerLink, 'ссылка в шапке').toHaveAttribute('href', '/calculator', LOAD);
      await expect(footerLink, 'ссылка в футере').toHaveAttribute('href', '/calculator');

      if (tag === '@desktop') {
        await headerLink.click();
        await page.waitForURL(/\/calculator$/);
        await expect(page.getByRole('heading', { level: 1, name: 'מחשבון כדאיות רכישת עסק' })).toBeVisible(LOAD);
        await page.goto('/');
      }

      await footerLink.click();
      await page.waitForURL(/\/calculator$/);
      await expect(page.getByRole('heading', { level: 1, name: 'מחשבון כדאיות רכישת עסק' })).toBeVisible(LOAD);
    });
  }
});
